import type { VideoBreakdown, VideoItem } from './types';

const NO_DATA = '素材无法解析';

const formulaByDirection: Record<string, string> = {
  机制引入:
    '反差／利益机制钩子 ＋ 机制说明 ＋ 实物展示 ＋ 稀缺强化 ＋ 转化引导',
  功效卖点: '效果钩子 ＋ 痛点直击 ＋ 使用过程 ＋ 效果验证 ＋ 转化引导',
  场景营销: '场景代入 ＋ 痛点触发 ＋ 商品解决方案 ＋ 使用证明 ＋ 行动引导',
  价格利益: '价格锚点 ＋ 优惠解释 ＋ 商品展示 ＋ 到手利益 ＋ 限时催单',
  口碑背书: '人群痛点 ＋ 口碑／资质背书 ＋ 体验证明 ＋ 卖点强化 ＋ 转化引导',
  测评种草: '结果前置 ＋ 测试过程 ＋ 对比证明 ＋ 适用人群 ＋ 购买引导',
};

const stopWords = new Set([
  '视频',
  '商品',
  '产品',
  '展示',
  '通过',
  '强调',
  '强化',
  '引导',
  '用户',
  '使用',
  '素材',
  '中段',
  '结尾',
  '前3s',
  '前3秒',
  '画面',
  '字幕',
  '内容',
  '直接',
  '进行',
]);

export function formatPercent(value?: number | null) {
  if (typeof value !== 'number' || Number.isNaN(value)) return '—';
  return `${(value * 100).toFixed(2)}%`;
}

export function formatNumber(value?: number | null) {
  if (typeof value !== 'number' || Number.isNaN(value)) return '—';
  if (value >= 100000000) return `${(value / 100000000).toFixed(1)} 亿`;
  if (value >= 10000) return `${(value / 10000).toFixed(1)} 万`;
  return Math.round(value).toLocaleString('zh-CN');
}

export function formatDuration(value?: number | null) {
  if (typeof value !== 'number' || Number.isNaN(value)) return '—';
  const seconds = value > 1000 ? value / 1000 : value;
  return `${Math.round(seconds)}s`;
}

function extractHashtags(title?: string | null) {
  const tags = (title ?? '').match(/#[^#\s，。！!？?]+/g) ?? [];
  return tags.slice(0, 4).map(tag => tag.replace('#', ''));
}

function extractSellingPoints(item: VideoItem) {
  const source =
    `${item.videoTitle ?? ''}；${item.bestsellerContentAnalysis ?? ''}`
      .replace(/[“”'"（）()]/g, '')
      .split(/[，。；、：:+]/)
      .map(part => part.trim())
      .filter(part => part.length >= 3 && part.length <= 18)
      .filter(part => ![...stopWords].some(word => part === word))
      .filter(part =>
        /省|低|高|强|轻|快|持久|防|控|柔|香|净|鲜|营养|方便|限定|联名|赠|优惠|舒适|安全|成分|效果|体验|适合|解决|改善|显|耐|保湿|遮瑕|清洁/.test(
          part,
        ),
      );
  return [...new Set(source)].slice(0, 6);
}

function inferScene(item: VideoItem) {
  const text = `${item.videoTitle ?? ''}${item.bestsellerContentAnalysis ?? ''}`;
  const scenes = [
    ['通勤', '日常通勤使用场景'],
    ['上班', '职场／上班使用场景'],
    ['居家', '居家使用场景'],
    ['厨房', '家庭厨房使用场景'],
    ['浴室', '浴室清洁／洗护场景'],
    ['户外', '户外使用场景'],
    ['出行', '出行使用场景'],
    ['旅行', '旅行便携场景'],
    ['宝宝', '母婴照护场景'],
    ['宠物', '宠物日常养护场景'],
    ['零食', '休闲零食消费场景'],
    ['妆', '日常妆容／护肤场景'],
    ['清洁', '家庭清洁场景'],
    ['穿搭', '日常穿搭场景'],
    ['睡眠', '睡眠／卧室场景'],
  ];
  const matched = scenes.find(([keyword]) => text.includes(keyword));
  if (matched) return matched[1];
  if (item.category) return `${item.category}的实际展示与使用场景`;
  return NO_DATA;
}

export function buildBreakdown(item: VideoItem): VideoBreakdown {
  const hashtags = extractHashtags(item.videoTitle);
  const sellingPoints = extractSellingPoints(item);
  const direction = item.creativeDirection ?? '';
  const formula =
    formulaByDirection[direction] ??
    (item.bestsellerContentAnalysis
      ? `${direction || '内容'}钩子 ＋ 核心信息展开 ＋ 过程／实物证明 ＋ 转化引导`
      : NO_DATA);

  return {
    前3秒内容:
      item.pre3sScript ||
      item.bestsellerContentAnalysis?.split(/[；。]/)[0] ||
      NO_DATA,
    视频公式: formula,
    关联热点: hashtags.length ? `${hashtags.join(' ＋ ')} 的组合表达` : NO_DATA,
    视频类型:
      [item.videoType, item.creativeDirection].filter(Boolean).join(' · ') ||
      NO_DATA,
    视频场景: inferScene(item),
    商品卖点: sellingPoints.length ? sellingPoints.join('、') : NO_DATA,
  };
}

function mode(items: string[]) {
  const counts = new Map<string, number>();
  for (const item of items.filter(Boolean))
    counts.set(item, (counts.get(item) ?? 0) + 1);
  return (
    [...counts.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ??
    '暂无明显集中项'
  );
}

function median(values: number[]) {
  const sorted = values.filter(Number.isFinite).sort((a, b) => a - b);
  if (!sorted.length) return 0;
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

export function buildInsights(items: VideoItem[]) {
  const directions = items
    .map(item => item.creativeDirection ?? '')
    .filter(Boolean);
  const types = items.map(item => item.videoType ?? '').filter(Boolean);
  const durations = items
    .map(item => item.videoDuration ?? NaN)
    .filter(Number.isFinite);
  const medianSecondsRaw = median(durations);
  const medianSeconds =
    medianSecondsRaw > 1000 ? medianSecondsRaw / 1000 : medianSecondsRaw;
  const ctrItems = items
    .filter(item => typeof item.ctr === 'number')
    .sort((a, b) => (a.ctr ?? 0) - (b.ctr ?? 0));
  const lowItems = ctrItems.slice(
    0,
    Math.max(1, Math.ceil(ctrItems.length * 0.2)),
  );
  const lowDirection = mode(lowItems.map(item => item.creativeDirection ?? ''));
  const topDirection = mode(directions);
  const topType = mode(types);

  return {
    highlights: [
      `当前榜单共收录 ${items.length} 条真实素材，主导创意方向是「${topDirection}」。`,
      `高频视频类型集中在「${topType}」，时长中位数约 ${Math.round(medianSeconds || 0)} 秒。`,
      `榜单按行业星川消耗排序，卡片保留 3 秒播放、CTR、CVR 等客观指标。`,
    ],
    pitfalls: [
      lowDirection === '暂无明显集中项'
        ? '低效素材未呈现稳定共性，建议优先核查前 3 秒信息是否完整。'
        : `CTR 后 20% 的素材中「${lowDirection}」出现较多，需避免只讲概念、缺少可见证明。`,
      '标题、字幕或画面没有明确利益点时，不补充主观卖点，统一标记为「素材无法解析」。',
      '避免把评论情绪或外部经验当作素材事实，结论仅来自画面、字幕、人声与音效。',
    ],
    suggestions: [
      `优先复用「${topDirection}」的前 3 秒组织方式，并在首屏同步给出商品或结果。`,
      `建议将主体内容控制在约 ${Math.max(10, Math.round(medianSeconds || 20))} 秒，并用实物／过程镜头完成证明。`,
      '同一卖点至少安排“字幕点题＋画面证明”两种表达，再补充清晰的转化动作。',
    ],
  };
}
