import { FilterBar } from '@/components/FilterBar';
import { HeroHeader } from '@/components/HeroHeader';
import { InsightGrid } from '@/components/InsightGrid';
import { EmptyState, LoadMore } from '@/components/ListStates';
import { VideoCard } from '@/components/VideoCard';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { buildInsights } from '@/data/analysis';
import rankDataJson from '@/data/rank-data.json';
import type { RankData, TimeRange, VideoItem } from '@/data/types';
import { Database, Info, Layers3 } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';

const rankData = rankDataJson as RankData;
const INDUSTRY_ORDER = [
  '个护美妆',
  '家清纸品',
  '服饰&家居电器',
  '母婴宠物',
  '食品饮料',
];
const PAGE_SIZE = 12;

export default function Page() {
  const [industry, setIndustry] = useState(INDUSTRY_ORDER[0]);
  const [timeRange, setTimeRange] = useState<TimeRange>('7d');
  const [query, setQuery] = useState('');
  const [visibleCount, setVisibleCount] = useState(PAGE_SIZE);

  const currentRange = rankData.ranges[timeRange] ?? [];
  const industryItems = useMemo(
    () =>
      currentRange
        .filter(item => item.industry === industry)
        .sort(
          (a, b) =>
            (a.industryConsumptionRank ?? a.rank ?? 999) -
            (b.industryConsumptionRank ?? b.rank ?? 999),
        )
        .slice(0, 100),
    [currentRange, industry],
  );
  const filteredItems = useMemo(() => {
    const keyword = query.trim().toLowerCase();
    if (!keyword) return industryItems;
    return industryItems.filter(item =>
      [
        item.videoTitle,
        item.category,
        item.productSubCategory,
        item.pre3sScript,
        item.bestsellerContentAnalysis,
      ].some(value => value?.toLowerCase().includes(keyword)),
    );
  }, [industryItems, query]);
  const insights = useMemo(() => buildInsights(industryItems), [industryItems]);
  const visibleItems = filteredItems.slice(0, visibleCount);

  useEffect(() => setVisibleCount(PAGE_SIZE), [industry, timeRange, query]);

  const reset = () => {
    setIndustry(INDUSTRY_ORDER[0]);
    setTimeRange('7d');
    setQuery('');
  };

  return (
    <main className="min-h-screen bg-zinc-50 text-zinc-900" data-aime-component-name="main"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="5"  data-aime-line="67"  data-insp-path="src/routes/page.tsx:67:5:main" >
      <div className="mx-auto max-w-screen-2xl space-y-10 px-4 py-6 md:px-8 lg:space-y-14 lg:py-10" data-aime-component-name="div"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="7"  data-aime-line="68"  data-insp-path="src/routes/page.tsx:68:7:div" >
        <HeroHeader
          updatedAt={rankData.updatedAt}
          sourceUrl={rankData.source}
         data-aime-component-name="HeroHeader"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="9"  data-aime-line="69"  data-insp-path="src/routes/page.tsx:69:9:HeroHeader" />
        <FilterBar
          industries={INDUSTRY_ORDER}
          industry={industry}
          setIndustry={setIndustry}
          timeRange={timeRange}
          setTimeRange={setTimeRange}
          query={query}
          setQuery={setQuery}
          count={filteredItems.length}
         data-aime-component-name="FilterBar"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="9"  data-aime-line="73"  data-insp-path="src/routes/page.tsx:73:9:FilterBar" />

        <InsightGrid insights={insights}  data-aime-component-name="InsightGrid"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="9"  data-aime-line="84"  data-insp-path="src/routes/page.tsx:84:9:InsightGrid" />

        {industryItems.length < 100 ? (
          <Alert className="rounded-2xl border-violet-100 bg-violet-50 text-violet-950" data-aime-component-name="Alert"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="11"  data-aime-line="87"  data-insp-path="src/routes/page.tsx:87:11:Alert" >
            <Info className="text-violet-600" size={18}  data-aime-component-name="Info"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="13"  data-aime-line="88"  data-insp-path="src/routes/page.tsx:88:13:Info" />
            <AlertTitle data-aime-component-name="AlertTitle" data-aime-path-name="src/routes/page.tsx" data-aime-column="13" data-aime-line="89" data-insp-path="src/routes/page.tsx:89:13:AlertTitle">当前周期数据已完整展示</AlertTitle>
            <AlertDescription data-aime-component-name="AlertDescription" data-aime-path-name="src/routes/page.tsx" data-aime-column="13" data-aime-line="90" data-insp-path="src/routes/page.tsx:90:13:AlertDescription">
              近 7 天源榜单当前仅返回每行业 {industryItems.length} 条；近 14
              天和近 30 天均支持每行业 Top 100。页面不会复制或推算不存在的素材。
            </AlertDescription>
          </Alert>
        ) : null}

        <section aria-labelledby="video-list-title" data-aime-component-name="section"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="9"  data-aime-line="97"  data-insp-path="src/routes/page.tsx:97:9:section" >
          <div className="mb-5 flex flex-col justify-between gap-3 md:flex-row md:items-end" data-aime-component-name="div"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="11"  data-aime-line="98"  data-insp-path="src/routes/page.tsx:98:11:div" >
            <div data-aime-component-name="div" data-aime-path-name="src/routes/page.tsx" data-aime-column="13" data-aime-line="99" data-insp-path="src/routes/page.tsx:99:13:div">
              <p className="flex items-center gap-2 text-sm font-semibold text-violet-600" data-aime-component-name="p"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="15"  data-aime-line="100"  data-insp-path="src/routes/page.tsx:100:15:p" >
                <Layers3 size={16}  data-aime-component-name="Layers3"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="17"  data-aime-line="101"  data-insp-path="src/routes/page.tsx:101:17:Layers3" /> CONTENT BREAKDOWN
              </p>
              <h2
                id="video-list-title"
                className="mt-1 text-2xl font-black tracking-tight"
               data-aime-component-name="h2"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="15"  data-aime-line="103"  data-insp-path="src/routes/page.tsx:103:15:h2" >
                具体数据详情拆解
              </h2>
            </div>
            <p className="text-sm text-zinc-500" data-aime-component-name="p"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="13"  data-aime-line="110"  data-insp-path="src/routes/page.tsx:110:13:p" >
              按行业星川消耗由高到低排序 · 点击封面播放原视频
            </p>
          </div>
          {visibleItems.length ? (
            <>
              <div className="grid gap-5 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4" data-aime-component-name="div"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="15"  data-aime-line="116"  data-insp-path="src/routes/page.tsx:116:15:div" >
                {visibleItems.map((item: VideoItem, index) => (
                  <VideoCard
                    key={`${timeRange}-${item.id}`}
                    item={item}
                    displayRank={index + 1}
                   data-aime-component-name="VideoCard"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="19"  data-aime-line="118"  data-insp-path="src/routes/page.tsx:118:19:VideoCard" />
                ))}
              </div>
              <LoadMore
                visible={visibleItems.length}
                total={filteredItems.length}
                onLoadMore={() =>
                  setVisibleCount(value =>
                    Math.min(value + PAGE_SIZE, filteredItems.length),
                  )
                }
               data-aime-component-name="LoadMore"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="15"  data-aime-line="125"  data-insp-path="src/routes/page.tsx:125:15:LoadMore" />
            </>
          ) : (
            <EmptyState reset={reset}  data-aime-component-name="EmptyState"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="13"  data-aime-line="136"  data-insp-path="src/routes/page.tsx:136:13:EmptyState" />
          )}
        </section>

        <section className="rounded-2xl border border-zinc-200 bg-white p-5 text-sm leading-6 text-zinc-600 shadow-sm" data-aime-component-name="section"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="9"  data-aime-line="140"  data-insp-path="src/routes/page.tsx:140:9:section" >
          <div className="flex gap-3" data-aime-component-name="div"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="11"  data-aime-line="141"  data-insp-path="src/routes/page.tsx:141:11:div" >
            <Database className="mt-0.5 flex-none text-violet-600" size={20}  data-aime-component-name="Database"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="13"  data-aime-line="142"  data-insp-path="src/routes/page.tsx:142:13:Database" />
            <div data-aime-component-name="div" data-aime-path-name="src/routes/page.tsx" data-aime-column="13" data-aime-line="143" data-insp-path="src/routes/page.tsx:143:13:div">
              <p className="font-bold text-zinc-900" data-aime-component-name="p"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="15"  data-aime-line="144"  data-insp-path="src/routes/page.tsx:144:15:p" >数据与判断口径</p>
              <p className="mt-1" data-aime-component-name="p"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="15"  data-aime-line="145"  data-insp-path="src/routes/page.tsx:145:15:p" >
                榜单数据来自营销参谋—千川短视频榜，以 2026 年 9 月 3
                日为周更新起点。内容判断仅依据素材中的画面、字幕、人声与音效；字段证据不足时统一标记为「素材无法解析」。
              </p>
            </div>
          </div>
        </section>
      </div>
      <footer className="border-t border-zinc-200 bg-white px-4 py-8 text-center text-xs leading-6 text-zinc-500" data-aime-component-name="footer"  data-aime-path-name="src/routes/page.tsx"  data-aime-column="7"  data-aime-line="153"  data-insp-path="src/routes/page.tsx:153:7:footer" >
        <p data-aime-component-name="p" data-aime-path-name="src/routes/page.tsx" data-aime-column="9" data-aime-line="154" data-insp-path="src/routes/page.tsx:154:9:p">由 曾美玉 创建 · 每周四更新</p>
        <p data-aime-component-name="p" data-aime-path-name="src/routes/page.tsx" data-aime-column="9" data-aime-line="155" data-insp-path="src/routes/page.tsx:155:9:p">页面数据可见性与所引用的数据源权限保持一致｜本页面由 Aime 创建</p>
      </footer>
    </main>
  );
}
